if (points.size() < 2) return {};

std::vector<std::vector<Point2d>> cells(points.size());
std::vector<std::vector<int>> adj(points.size());

auto circumcenter = [](const Point2d& a, const Point2d& b, const Point2d& c) -> Point2d {
    double d = 2 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
    if (std::abs(d) < 1e-10) return {0, 0};
    double ux = (a.x * a.x + a.y * a.y) * (b.y - c.y);
    double uy = (a.x * a.x + a.y * a.y) * (c.x - b.x);
    double vx = (b.x * b.x + b.y * b.y) * (c.y - a.y);
    double vy = (b.x * b.x + b.y * b.y) * (a.x - c.x);
    double wx = (c.x * c.x + c.y * c.y) * (a.y - b.y);
    double wy = (c.x * c.x + c.y * c.y) * (b.x - a.x);
    return {(ux + vx + wx) / d, (uy + vy + wy) / d};
};

for (size_t i = 0; i < points.size(); ++i) {
    for (size_t j = i + 1; j < points.size(); ++j) {
        for (size_t k = j + 1; k < points.size(); ++k) {
            bool valid = true;
            for (size_t m = 0; m < points.size(); ++m) {
                if (m == i || m == j || m == k) continue;
                Point2d cc = circumcenter(points[i], points[j], points[k]);
                double dx = points[m].x - cc.x;
                double dy = points[m].y - cc.y;
                double dist = dx * dx + dy * dy;
                double radius = (points[i].x - cc.x) * (points[i].x - cc.x) + (points[i].y - cc.y) * (points[i].y - cc.y);
                if (dist < radius - 1e-8) { valid = false; break; }
            }
            if (valid) {
                Point2d cc = circumcenter(points[i], points[j], points[k]);
                adj[i].push_back(j);
                adj[i].push_back(k);
                adj[j].push_back(i);
                adj[j].push_back(k);
                adj[k].push_back(i);
                adj[k].push_back(j);
            }
        }
    }
}

for (size_t i = 0; i < points.size(); ++i) {
    std::set<int> unique_adj(adj[i].begin(), adj[i].end());
    std::vector<int> neighbors(unique_adj.begin(), unique_adj.end());
    std::vector<Point2d> cell;
    for (size_t j = 0; j < neighbors.size(); ++j) {
        int k = (j + 1) % neighbors.size();
        Point2d cc = circumcenter(points[i], points[neighbors[j]], points[neighbors[k]]);
        cell.push_back(cc);
    }
    cells[i] = cell;
}

return cells;
// END_CODE

